import{_ as t,c as s,o as n,j as e,a as l}from"./chunks/framework.BKeRpnBD.js";const m=JSON.parse('{"title":"《伊川易传》简介","description":"伊川易传 - 《伊川易传》简介","frontmatter":{"title":"《伊川易传》简介","description":"伊川易传 - 《伊川易传》简介"},"headers":[],"relativePath":"zh/classics/yichuan/001.md","filePath":"zh/classics/yichuan/001.md"}'),r={name:"zh/classics/yichuan/001.md"};function c(i,a,o,p,d,u){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"《伊川易传》简介",tabindex:"-1"},[l("《伊川易传》简介 "),e("a",{class:"header-anchor",href:"#《伊川易传》简介","aria-label":"Permalink to “《伊川易传》简介”"},"​")],-1),e("p",null,"《伊川易传》是中国北宋时期著名哲学家、理学家程颐注解《周易》的哲学著作，也被称为《周易程氏传》或《程氏易传》。这部作品共4卷，大约15万字，由程颐在涪陵写成，成书于宋哲宗元符二年（1099年），当时程颐66岁。程颐在《易传序》中提出了“体用一源，显微无间”的理学命题，强调无形的理寓于有形的象中，理与象即是理与事的体用关系。",-1),e("p",null,"程颐在《伊川易传》中，借解释《周易》卦辞爻象来阐明义理，易象反映天地万物之物象，易理则概括了天地之理。他认为理不仅是天地万物的根本，也是社会等级、人生道德的由来，书中还包括了阴阳、动静变化的思想和关于理欲的观点，反映了程颐从宇宙自然到社会人生的较系统的哲学思想。",-1),e("p",null,"《伊川易传》从元代开始被列为科举必读书，其哲学思想在封建社会后期有过重大影响。程颐的这部作品不仅对《易经》的解释有独到之处，而且集中体现了他的理学思想，是程颐平生用力最多的著作。",-1),e("p",null,"程颐的《易传》在成书后，由于程颐本人对这部书非常重视，他去世后传本不一，杨时曾加编次。但在宋元时，其书编卷仍不一致。清康熙间吕留良定为4卷，汇入《二程全书》，后涂宗瀛又作校订。",-1),e("p",null,"《伊川易传》作为程颐理学思想的主干，是程朱学派的理学经典著作之一，其地位与朱熹的《四书集注》同样重要。程颐的这部著作对后世产生了深远的影响，成为宋明理学的重要著作。",-1)])])}const _=t(r,[["render",c]]);export{m as __pageData,_ as default};
